    fo = {"banca": "Fundação Cesgranrio", "concurso": c["concurso"], "cargo": c["cargo"], "ano": c["ano"], "prova": c["prova"], "numero_original": n,
          "id_prova": c["id_prova"], "situacao_gabarito": c["gab"], "aderencia_edital": ader, "url": BASE + c["arq"], "sha256": "ver docs/estrategia/base-provas.md"}
    rotulo = "Questão oficial — Fundação Cesgranrio, %s, %s, questão %d." % (c["concurso"].split(" (")[0], c["prova"].split(" (")[0], n)
    return (mod, questao("", "oficial", rotulo, mod, item, assunto, dif, hab, tq, enun, alts, gab, resol, an, ponto, rev,
                         fonte=fo, verif=verif, tags=list(tags) + [c["tag"]], sec=sec))
